customMethods.script:
self.view.custom.scrapOpen = not self.view.custom.scrapOpen
if self.view.custom.scrapOpen and not (self.view.custom.scrapLines or []):
	self.addScrapLine()

# requiresNote is passed through from the SQL code table
# (Workorder.DieCastVarianceReason.RequiresNote), never decided here.
req = False
for o in (BlueRidge.Common.Util.extractQualifiedValues(self.view.params.varianceReasonOptions) or []):
	o = o or {}
	if reasonId is not None and ("%s" % o.get("value")) == ("%s" % reasonId):
		req = bool(o.get("requiresNote"))
		break
self.view.custom.varianceReasonId = reasonId
self.view.custom.reasonRequiresNote = req
if reasonId is None:
	self.view.custom.varianceNote = ""
self.emitRowChanged()

# Close the gap where the operator noticed it (spec 6.3) --
# DieCastBody routes to Lot Management with this cavity in view.
system.perspective.sendMessage("dieCastOpenBasketRequested", payload={
	"toolCavityId": self.view.params.toolCavityId,
	"cavityName": self.view.params.cavityName or "",
}, scope="page")
